def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
table = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for a in bases:
    for b in bases:
        for c in bases:
            table[a+b+c]=aas[i]; i+=1
def translate(s):
    return ''.join(table.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))
def orfs(s, strand, minaa=60):
    out=[]
    for f in range(3):
        t=translate(s[f:])
        # split on stop
        start=0
        for j,ch in enumerate(t):
            if ch=='*':
                if j-start>=minaa:
                    nt_start=f+start*3; nt_end=f+j*3-1
                    if strand=='-':
                        nt_start=len(seq)-1-(f+j*3-1); nt_end=len(seq)-1-(f+start*3)
                    out.append((nt_start,nt_end,j-start,'-' if strand=='-' else '+'))
                start=j+1
        if len(t)-start>=minaa:
            nt_start=f+start*3; nt_end=f+len(t)*3-1
            out.append((nt_start,nt_end,len(t)-start,'-' if strand=='-' else '+'))
    return out
allorfs=[]
for s,strand in ((seq,'+'),(rc(seq),'-')):
    allorfs+=orfs(s,strand,60)
allorfs.sort()
for o in allorfs: print(o)
